  }
  const steps = Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 5);
  // Check the player's feet on both sides of the center line, including the
  // rounded movement cells immediately before and after the border.
  // A link declares its own opening; the check covers it, up to 60px wide.
  const half = Math.min(30, Math.floor(((link.width || 60) / 2 - 5) / 5) * 5);
  for (const offset of [-5, 0, 5])
    for (let along = -half; along <= half; along += 5) {
      const x = c[0] + (vertical ? offset : along),
        y = c[1] + (vertical ? along : offset);
      assert(r(`groundWalkable(${x},${y})`), `narrow or interrupted crossing ${link.from}/${link.to}`);
    }
  for (let n = 0; n <= steps; n++) {
    const x = a[0] + ((b[0] - a[0]) * n) / steps,
      y = a[1] + ((b[1] - a[1]) * n) / steps;
    assert(r(`groundWalkable(${x},${y})`), `blocked crossing ${link.from}/${link.to}: ${x},${y}`);
  }
  for (const forward of [true, false]) {
    const start = forward ? a : b,
      end = forward ? b : a;
    r(
      `state.region=${forward ? link.from : link.to};state.room=null;setWorldPosition(${start[0]},${start[1]})`,
    );
    const dx = Math.sign(end[0] - start[0]) * 5,
      dy = Math.sign(end[1] - start[1]) * 5;
    for (let n = 0; n < steps; n++) r(`movement(${dx},${dy})`);
    assert.equal(r('state.region'), forward ? link.to : link.from, 'walking crosses in both directions');
    // A region change must not move the camera sideways or expose an empty
    // diagonal cell at the corner of the shared paintings.
    r(
      `state.region=${forward ? link.from : link.to};setWorldPosition(${start[0]},${start[1]});cameraPosition(true)`,
    );
    let previous = r('({x:camera.x,y:camera.y})');
    for (let n = 0; n <= steps; n++) {
      r(`setWorldPosition(${start[0] + dx * n},${start[1] + dy * n});cameraPosition()`);
      const current = r('({x:camera.x,y:camera.y,width:camera.width,height:camera.height})');
      assert(
        Math.hypot(current.x - previous.x, current.y - previous.y) <= 5.01,
        'continuous camera at every shared edge',
      );
      const painted = [...origins, [r('GANG_WORLD.x'), r('GANG_WORLD.y')]];
      for (let y = current.y + 1; y < current.y + current.height; y += 20)
        for (let x = current.x + 1; x < current.x + current.width; x += 20)
          assert(
            painted.some(([ox, oy]) => x >= ox && x <= ox + 960 && y >= oy && y <= oy + 640),
            'continuous world view contains painted maps, not empty diagonal cells',
          );
      previous = current;
    }
  }
  // Both paintings must be visible while approaching the edge, in either
  // direction. Changing the region alone must not change the camera target.
  for (const side of [-1, 1]) {
    const x = c[0] + (vertical ? 0 : side * 120),
      y = c[1] + (vertical ? side * 120 : 0);
    r(
      `state.room=null;state.region=${link.from};state.x=${x - origins[link.from][0]};state.y=${y - origins[link.from][1]};cameraPosition(true)`,
    );
    const visible = r('visibleRegionIndices()'),
      before = r('({x:camera.x,y:camera.y})');
    assert(visible.includes(link.from) && visible.includes(link.to), 'neighbor visible before crossing');
    r(
      `state.region=${link.from};state.x=${x - origins[link.from][0]};state.y=${y - origins[link.from][1]};cameraPosition(true)`,
    );
    assert.deepEqual(r('({x:camera.x,y:camera.y})'), before, 'view does not depend on current map');
    r(
      `state.region=${link.to};state.x=${x - origins[link.to][0]};state.y=${y - origins[link.to][1]};cameraPosition(true)`,
    );
    assert.deepEqual(r('({x:camera.x,y:camera.y})'), before, 'no reveal mechanic on map change');
  }
}
