/* User exteriors are authoritative; the new interiors retain native generated pixels. */
const assert = require('node:assert/strict'),
  fs = require('node:fs'),
  crypto = require('node:crypto'),
  sharp = require('sharp');
const { setup, SCRIPT_ORDER } = require('./harness.cjs');
(async () => {
  const record = JSON.parse(fs.readFileSync('art/chapter-two-selected-2026-10-09.json'));
  assert.equal(record.generationAttempts, 4);
  assert.equal(record.retainedAttempts, 4);
  assert.equal(new Set(record.interiors.map(a => a.source)).size, 4);
  for (const a of [...record.selectedAssets, ...record.interiors]) {
    const m = await sharp(a.export).metadata();
    assert.equal(m.width, 1536);
    assert.equal(m.height, 1024);
    const hash = crypto.createHash('sha256').update(fs.readFileSync(a.export)).digest('hex');
    assert.equal(hash, a.sha256 || a.exportSHA256, 'accepted native asset ' + a.export);
    if (a.source) {
      const source = await sharp(a.source).removeAlpha().raw().toBuffer(),
        out = await sharp(a.export).removeAlpha().raw().toBuffer();
      assert(source.equals(out), 'lossless export, no scale/crop ' + a.key);
    }
  }
  const normal = setup().run;
  for (const key of ['warungcity', 'gym', 'stage', 'mallatrium', 'clinic', 'terminalshop', 'pasarsubuh'])
    assert(
      fs.existsSync('web/' + normal(`ROOMS[${JSON.stringify(key)}].image`)),
      'room image exists: ' + key,
    );
  for (const a of record.retainedDistricts) {
    assert(fs.readFileSync(a.source).equals(fs.readFileSync(a.export)), 'auxiliary room original bytes');
    assert.equal(crypto.createHash('sha256').update(fs.readFileSync(a.export)).digest('hex'), a.sha256);
  }
  const stale = {
    version: 1,
    maps: {
      0: { image: normal('PLACES[0].image'), rows: normal('FLOORS[0]') },
      3: { image: normal('PLACES[3].image'), rows: Array(65).fill('.'.repeat(97)) },
    },
  };
  const migrated = setup({ 'wargamon-floor-edits-v1': JSON.stringify(stale) }).run;
  assert(migrated('floorEdits[0]'));
  assert.equal(migrated('floorEdits[3]'), undefined);
  const g = setup(
      {},
      {
        afterScript(file, s) {
          if (file === SCRIPT_ORDER[0]) {
            s.location = { search: '?debug' };
            s.sessionStorage = { getItem: () => null, setItem() {} };
            s.document.body.append = () => {};
          }
        },
      },
    ),
    r = g.run;
  for (const a of record.selectedAssets) {
    assert.equal(r(`floorEditImage('${a.region}')`), a.export.replace(/^web\//, ''));
    r(
      `setEditedFloor('${a.region}',FLOORS[${a.region}].map((row,i)=>i===10?row.slice(0,48)+(row[48]==='#'?'.':'#')+row.slice(49):row))`,
    );
    assert.equal(r(`floorEditArchive().maps[${a.region}].revision`), r(`FLOOR_ART_REVISIONS[${a.region}]`));
  }
  console.log(
    'PASS four accepted native user exteriors, four separate lossless native interiors, all generation attempts retained, correct editor image associations and selective floor-draft migration',
  );
})().catch(e => {
  console.error(e);
  process.exitCode = 1;
});

