  }
  for (const [key, x, y] of [
    [1, 300, 430], // clear meadow
    [1, 510, 585], // entrance road
    [1, 930, 530], // east dirt road
    [2, 100, 510], // west dirt road
    [2, 470, 60], // upper lake trail
    [2, 940, 290], // eastern lake trail
    ['gang', 145, 220], // gate
    ['gang', 345, 310], // food-stall approach
    ['gang', 450, 375], // lower alley
