    ['gang', 300, 235], // stall roof
    ['gang', 500, 260], // house
    ['gang', 730, 150], // canal
    ['gang', 530, 535], // river
  ])
    assert(!r(`effectiveFloorAt(${JSON.stringify(key)},${x},${y})`), `solid scenery ${key} ${x},${y}`);
  crossing(r, 0, { offsets: [-10, 0, 10] });
  crossing(r, 1, { offsets: [-10, 0, 10] });

  // Exercise the actual activity-approach code, including standing people. Capture
  // its route instead of running the animated follower in this Node harness.
  r('var testedApproach=null;followWorldPath=async path=>{testedApproach=path;return false;}');
  for (const i of [1, 2, 'gang']) {
    const count = r(i === 'gang' ? 'GANG_POINTS.length' : `regionPoints(${i}).length`);
    for (let n = 0; n < count; n++) {
