      assert(r('testedApproach?.length>0'), `reachable activity: ${name}`);
      assert(r('testedApproach.every(p=>worldWalkable(p.x,p.y))'), `valid route: ${name}`);
      assert(
        r(
          `(()=>{const t=globalPoint(${region},${point}),p=testedApproach.at(-1);return Math.hypot(p.x-t.x,p.y-t.y)<66;})()`,
        ),
        `close enough to use: ${name}`,
