      '(()=>{const p=testedApproach.at(-1),[x,y]=ROOMS.gangsenggol.spawn;return gangContains(p.x,p.y)&&Math.hypot(p.x-GANG_WORLD.x-x,p.y-GANG_WORLD.y-y)<10;})()',
    ),
