    const flood = open => {
      const seen=new Set(),queue=[[480,320]];
      for(let k=0;k<queue.length;k++) {
        const [x,y]=queue[k],key=x+','+y;
        if(seen.has(key)||!open(x,y))continue;
        seen.add(key);
        for(const [dx,dy] of [[10,0],[-10,0],[0,10],[0,-10]])queue.push([x+dx,y+dy]);
      }
      return seen;
    };
    const far={x:-999,y:-999},
      free=(x,y)=>groundWalkable(x,y)&&!personBlocks(worldPeople(),x,y,far),
      ground=flood(groundWalkable),walking=flood(free);
