const assert = require('node:assert/strict');
const { setup, SCRIPT_ORDER } = require('./harness.cjs');

function editor(key = '0', captureFails = false) {
  const game = setup(
    {},
    {
      afterScript(file, sandbox) {
        if (file !== SCRIPT_ORDER[0]) return;
        sandbox.location = { search: '?debug', hostname: 'example.test' };
        sandbox.sessionStorage = { getItem: () => null, setItem() {} };
        sandbox.document.body.append = () => {};
      },
    },
  );
  const run = game.run,
    handlers = {},
    surface =
      game.nodes.get('floorEditorCanvas') ||
      (run("$('floorEditorCanvas')"), game.nodes.get('floorEditorCanvas'));
  surface.addEventListener = (type, fn) => (handlers[type] ??= []).push(fn);
  surface.getContext = () => ({
    clearRect() {},
    fillRect() {},
    drawImage() {},
    save() {},
    restore() {},
    setLineDash() {},
    strokeRect() {},
  });
  surface.setPointerCapture = () => {
    if (captureFails) throw new Error('Capture unavailable');
  };
  run(`state.room=${key === '0' ? 'null' : JSON.stringify(key)};state.region=0;
    closeModal(true);openFloorEditor();floorEditor.fill='blocked'`);
  const before = run('JSON.stringify(effectiveFloorRows(floorEditor.key))');
  const send = (target, type, col, row, extra = {}) => {
    const event = {
      pointerId: 1,
      pointerType: 'mouse',
      isPrimary: true,
      button: 0,
      buttons: 1,
      clientX: col * 10,
      clientY: row * 10,
      target: surface,
      preventDefault() {},
      ...extra,
    };
    const listeners = target === 'surface' ? handlers : game.listeners;
    for (const fn of listeners[type] || []) fn(event);
  };
  return { game, run, send, before };
}

// Unexpected capture loss must retain a completed drag, rather than silently discard it.
for (const key of ['0', 'stage']) {
  const { run, send } = editor(key);
  send('surface', 'pointerdown', 47, 32);
  send('surface', 'pointermove', 49, 34);
  send('document', 'pointermove', 49, 34);
  send('surface', 'lostpointercapture', 49, 34);
  assert.equal(run('floorEditor.stroke'), null);
  assert(run('floorEditor.selection'), 'capture loss retains the first block selection');
  assert(
    run('effectiveFloorRows(floorEditor.key).slice(32,35).every(row=>row.slice(47,50)==="...")'),
    'first rectangle is committed after capture loss',
  );
  assert.equal(run('floorEditor.undo.length'), 1);
  // The following drag must start immediately, with no extra attempt.
  send('surface', 'pointerdown', 51, 32);
  send('document', 'pointerup', 53, 34, { buttons: 0 });
  assert(run('effectiveFloorRows(floorEditor.key).slice(32,35).every(row=>row.slice(51,54)==="...")'));
  assert.equal(run('floorEditor.undo.length'), 2);
}

// A lost release cannot leave a stale stroke that consumes the next pointerdown.
const stale = editor();
stale.send('surface', 'pointerdown', 47, 32);
stale.send('surface', 'pointermove', 49, 34);
stale.send('document', 'pointermove', 49, 34);
stale.send('surface', 'pointerdown', 51, 32);
assert.deepEqual(Array.from(stale.run('floorEditor.stroke.start')), [51, 32]);
stale.send('document', 'pointerup', 53, 34, { buttons: 0 });
assert.equal(stale.run('floorEditor.undo.length'), 2, 'both gestures are separate undo actions');

// Document-level release completes a fast drag even when native capture fails.
const fallback = editor('stage', true);
assert.doesNotThrow(() => fallback.send('surface', 'pointerdown', 47, 32));
fallback.send('document', 'pointermove', 49, 34);
fallback.send('document', 'pointercancel', 49, 34, { pointerId: 2 });
assert(fallback.run('floorEditor.stroke'), 'another pointer cannot cancel this drag');
fallback.send('document', 'pointerup', 53, 35, { buttons: 0 });
assert(fallback.run('effectiveFloorRows("stage").slice(32,36).every(row=>row.slice(47,54)===".......")'));
assert.equal(fallback.run('floorEditor.stroke'), null);

// An actual cancellation keeps the floor unchanged; a hover after missed release cannot paint.
const cancelled = editor();
cancelled.send('surface', 'pointerdown', 47, 32);
cancelled.send('document', 'pointermove', 49, 34);
cancelled.send('document', 'pointercancel', 49, 34);
assert.equal(cancelled.run('JSON.stringify(effectiveFloorRows(floorEditor.key))'), cancelled.before);
assert.equal(cancelled.run('floorEditor.selection'), null);
const hover = editor();
hover.send('surface', 'pointerdown', 47, 32);
hover.send('document', 'pointermove', 49, 34);
hover.send('document', 'pointermove', 60, 50, { buttons: 0 });
assert.equal(hover.run('floorEditor.stroke'), null);
assert.deepEqual(Array.from(hover.run('floorEditor.selection.last')), [49, 34]);
assert.equal(hover.run('floorEditor.undo.length'), 1);

console.log(
  'PASS first-drag block edits, lost capture/release recovery, fast release outside canvas, pointer ownership and real cancellation in exterior/interior editors',
);

/* Exercise permanent saves against an isolated checkout, never the user's actual floor. */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const vm = require('node:vm');
const { spawn, spawnSync } = require('node:child_process');
const root = path.join(__dirname, '..');

(async () => {
  const fixture = fs.mkdtempSync(path.join(os.tmpdir(), 'wargamon-editor-'));
  const copy = name => {
    const target = path.join(fixture, name);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.copyFileSync(path.join(root, name), target);
  };
  const names = [
    'art/floors.json',
    'web/js/data/floors.js',
    'web/service-worker.js',
    'web/source-manifest.json',
  ];
  for (const name of [
    ...names,
    'web/img/maps/exterior/1-1.webp',
    'web/img/maps/exterior/1-2.webp',
    'web/img/maps/interior/warung-staff.webp',
    'web/img/maps/interior/wargamaret-staff.webp',
    'web/img/maps/interior/interiors.webp',
    'scripts/build-floors.cjs',
    'scripts/build-offline-cache.py',
    'scripts/update-source-manifest.py',
    'README.md',
    'RELEASE.md',
    'package.json',
    'requirements-art.txt',
  ])
    copy(name);
  fs.symlinkSync(path.join(root, 'node_modules'), path.join(fixture, 'node_modules'), 'dir');
  fs.writeFileSync(path.join(fixture, 'web/index.html'), '<script src="js/data/floors.js"></script>');
  const config = JSON.parse(fs.readFileSync(path.join(fixture, names[0]), 'utf8'));
  config.maps = Object.fromEntries(
    ['0', '1', 'warung', 'shop', 'terminalshop', 'mbg', 'canteen'].map(key => [key, config.maps[key]]),
  );
  fs.writeFileSync(path.join(fixture, names[0]), JSON.stringify(config));
  const floors = () => vm.runInNewContext(fs.readFileSync(path.join(fixture, names[1]), 'utf8') + '; FLOORS');
  const original = Array.from(floors()[0]);
  const rows = [...original];
  rows[32] = rows[32].slice(0, 51) + '.' + rows[32].slice(52);
  const loadServer = `import importlib.util\nspec=importlib.util.spec_from_file_location('editor',${JSON.stringify(path.join(root, 'scripts/dev-server.py'))})\nmodule=importlib.util.module_from_spec(spec)\nspec.loader.exec_module(module)\nserver=module.make_server(${JSON.stringify(fixture)},0,${JSON.stringify(process.execPath)})\nprint(server.server_port,flush=True)\nserver.serve_forever()`;
  const server = spawn('python3', ['-u', '-c', loadServer], { stdio: ['ignore', 'pipe', 'pipe'] });
  let log = '';
  server.stderr.on('data', data => {
    log += data;
  });
  try {
    const port = await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('Editor server did not start: ' + log)), 5000);
      server.stdout.once('data', data => {
        clearTimeout(timeout);
        resolve(Number(String(data).trim()));
      });
      server.once('error', error => {
        clearTimeout(timeout);
        reject(error);
      });
    });
    const url = `http://127.0.0.1:${port}/__editor/floors`;
    const capability = await (await fetch(url)).json();
    const payload = {
      version: 1,
      revision: capability.revision,
      maps: { 0: { image: config.maps[0].image, rows } },
    };
    const post = (data = payload, headers = {}) =>
      fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Wargamon-Editor': capability.token,
          ...headers,
        },
        body: JSON.stringify(data),
      });
    const snapshot = () => names.map(name => fs.readFileSync(path.join(fixture, name), 'utf8'));
    const before = snapshot();
    assert.equal((await post(payload, { 'X-Wargamon-Editor': 'wrong' })).status, 403);
    assert.equal((await post(payload, { Origin: 'https://elsewhere.example' })).status, 403);
    const badHost = await new Promise((resolve, reject) => {
      require('node:http')
        .get(url, { headers: { Host: 'elsewhere.example' } }, response => {
          response.resume();
          response.on('end', () => resolve(response.statusCode));
        })
        .on('error', reject);
    });
    assert.equal(badHost, 403);
    assert.equal((await post({ ...payload, maps: { '../elsewhere': payload.maps[0] } })).status, 400);
    assert.equal(
      (await post({ ...payload, maps: { 0: { ...payload.maps[0], rows: ['bad'] } } })).status,
      400,
    );
    assert.deepEqual(snapshot(), before, 'rejected requests cannot alter any project files');
    const response = await post();
    assert.equal(response.status, 200, await response.clone().text());
    const saved = await response.json();
    assert.deepEqual(saved.saved, ['0']);
    assert.deepEqual(Array.from(floors()[0]), rows, 'generated default matches the painted grid');
    const stored = JSON.parse(fs.readFileSync(path.join(fixture, names[0]), 'utf8'));
    assert.deepEqual(stored.maps[0].rows, rows);
    assert.deepEqual(stored.maps[1], config.maps[1], 'unselected map source is untouched');
    const rebuild = spawnSync(process.execPath, ['scripts/build-floors.cjs'], {
      cwd: fixture,
      encoding: 'utf8',
    });
    assert.equal(rebuild.status, 0, rebuild.stderr);
    assert.deepEqual(Array.from(floors()[0]), rows, 'a full rebuild retains permanent painting');
    // Editing the original shared floor cannot leak into an untouched sibling on rebuild.
    const siblingBefore = Array.from(floors().terminalshop);
    const changedShop = Array.from(floors().shop);
    const lastRow = changedShop.findLastIndex(line => line.includes('#'));
    const lastCol = changedShop[lastRow].lastIndexOf('#');
    changedShop[lastRow] =
      changedShop[lastRow].slice(0, lastCol) + '.' + changedShop[lastRow].slice(lastCol + 1);
    const parentSave = await post({
      version: 1,
      revision: (await (await fetch(url)).json()).revision,
      maps: { shop: { image: config.maps.shop.image, rows: changedShop } },
    });
    assert.equal(parentSave.status, 200, await parentSave.clone().text());
    const parentRebuild = spawnSync(process.execPath, ['scripts/build-floors.cjs'], {
      cwd: fixture,
      encoding: 'utf8',
    });
    assert.equal(parentRebuild.status, 0, parentRebuild.stderr);
    assert.deepEqual(
      Array.from(floors().terminalshop),
      siblingBefore,
      'parent save and full rebuild leave the unedited interior unchanged',
    );
    // An interior and a room that initially shares another floor save separately.
    const indoorRows = Array.from(floors().warung),
      aliasRows = Array.from(floors().terminalshop);
    const parentRows = Array.from(floors().shop);
    for (const grid of [indoorRows, aliasRows]) {
      const row = grid.findIndex(line => line.includes('#')),
        col = grid[row].indexOf('#');
      grid[row] = grid[row].slice(0, col) + '.' + grid[row].slice(col + 1);
    }
    const indoorSave = await post({
      version: 1,
      revision: (await (await fetch(url)).json()).revision,
      maps: {
        warung: { image: config.maps.warung.image, rows: indoorRows },
        terminalshop: { image: config.maps.terminalshop.image, rows: aliasRows },
      },
    });
    assert.equal(indoorSave.status, 200, await indoorSave.clone().text());
    assert.deepEqual((await indoorSave.json()).saved, ['warung', 'terminalshop']);
    assert.deepEqual(Array.from(floors().warung), indoorRows);
    assert.deepEqual(Array.from(floors().terminalshop), aliasRows);
    assert.deepEqual(
      Array.from(floors().shop),
      parentRows,
      'saving a shared room does not change its parent',
    );
    assert.deepEqual(Array.from(floors()[0]), rows, 'interior save does not affect the exterior');
    const interiorRebuild = spawnSync(process.execPath, ['scripts/build-floors.cjs'], {
      cwd: fixture,
      encoding: 'utf8',
    });
    assert.equal(interiorRebuild.status, 0, interiorRebuild.stderr);
    assert.deepEqual(
      Array.from(floors().terminalshop),
      aliasRows,
      'a complete rebuild retains the independent interior grid',
    );
    assert.deepEqual(Array.from(floors().shop), parentRows);
    assert.equal((await post()).status, 409, 'stale editors cannot overwrite newer source');
    // A build error must restore both source and generated data.
    const latest = await (await fetch(url)).json();
    capability.revision = latest.revision;
    const after = snapshot();
    fs.writeFileSync(
      path.join(fixture, 'scripts/build-floors.cjs'),
      'throw new Error("test build failure");',
    );
    assert.equal((await post({ ...payload, revision: latest.revision })).status, 500);
    assert.deepEqual(snapshot(), after, 'failed builds restore every file exactly');
    console.log(
      'PASS local editor API, authorization, validation, isolated exterior/interior and shared-room saves, rebuild persistence, conflict detection and failed-build rollback',
    );
  } finally {
    server.kill();
    await new Promise(resolve => server.once('exit', resolve));
    fs.rmSync(fixture, { recursive: true, force: true });
  }
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

