async function projectSaveChecks() {
  const writer = debugGame(),
    w = writer.run;
  w(
    "floorEditor.key='0';floorEditor.server={token:'test-token',revision:'r0'};var draft=[...FLOORS[0]];floorEditorPaintCell(draft,51,32,false);commitFloorEditor('0',FLOORS[0],draft)",
  );
  let request;
  writer.sandbox.fetch = async (url, options) => {
    request = { url, options, data: JSON.parse(options.body) };
    return { ok: true, json: async () => ({ saved: ['0'], revision: 'r1' }) };
  };
  assert(await w('saveFloorEditorProject()'));
  assert.equal(request.url, '/__editor/floors');
  assert.equal(request.options.headers['X-Wargamon-Editor'], 'test-token');
  assert.deepEqual(Object.keys(request.data.maps), ['0'], 'save writes only the selected map');
  assert.equal(request.data.maps[0].rows[32][51], '.');
  assert.equal(w('FLOORS[0][32][51]'), '.', 'successful save updates the in-memory default');
  assert.equal(w('floorEdits[0]'), undefined, 'saved draft no longer masks the codebase floor');
  assert.equal(w('floorEditor.server.revision'), 'r1');
  w('floorEditorHistory()');
  assert(w('localTerrain(0,510,320)'), 'undo after permanent save creates a new draft');
  const baseline = w('JSON.stringify(FLOORS[0])');
  writer.sandbox.fetch = async () => ({ ok: false, status: 500 });
  assert.equal(await w('saveFloorEditorProject()'), false);
  assert.equal(w('JSON.stringify(FLOORS[0])'), baseline, 'failed writes do not change defaults');
  assert(w('floorEdits[0]'), 'failed writes retain the draft');
  assert.equal(w('floorEditor.writing'), false);
  // A user can continue painting during a save; those newer cells must stay as a draft.
  let reply;
  writer.sandbox.fetch = () =>
    new Promise(resolve => {
      reply = resolve;
    });
  const saving = w('saveFloorEditorProject()');
  w(
    "var newer=[...effectiveFloorRows('0')];floorEditorPaintCell(newer,52,32,false);commitFloorEditor('0',effectiveFloorRows('0'),newer)",
  );
  reply({ ok: true, json: async () => ({ saved: ['0'], revision: 'r2' }) });
  assert(await saving);
  assert.equal(w('FLOORS[0][32][52]'), '#', 'server result is the submitted snapshot');
  assert.equal(w('floorEdits[0].rows[32][52]'), '.', 'painting after submission is preserved');
  assert.equal(await normal.run('saveFloorEditorProject()'), false, 'normal play cannot write the project');
  console.log(
    'PASS Sukamaju floor, rectangle/brush editing, undo/redo, drafts, import validation, permanent save, write failure and concurrent painting',
  );
}
projectSaveChecks().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { setup } = require('./harness.cjs');

async function main() {
  const game = setup(),
    run = game.run;
  run(`closeModal(true);state.region=1;state.room=null;
    [state.x,state.y]=PLACES[1].spawn;cameraPosition(true);
    state.team=[makeMon(0,5),makeMon(26,6)];
    startBattle(null,[[SPECIES.findIndex(s=>s.name==='Tempurayap'),6]]);
    state.team[0].hp=0`);
  const position = Array.from(run('[state.x,state.y]'));
  const money = run('state.money'),
    wins = run('state.wins');
  assert.equal(await run('partyFaint()'), false);
  assert.equal(run('followingMon().id'), 26, 'Layanganak replaces the fainted lead');
  run('battle.enemy.hp=0');
  await run('enemyDefeated()');
  assert.equal(run('battle'), null);
  assert.equal(run('state.region'), 1);
  assert.deepEqual(Array.from(run('[state.x,state.y]')), position);
  assert.equal(run('state.money'), money + 6 * 150, 'a wild victory pays 150 per level of the foe');
  assert.equal(run('state.wins'), wins + 1);
  assert.equal(run('state.team[1].hp'), 0, 'the fainted teammate remains fainted');

  const name = 'img/followers/follower-layanganak.webp';
  assert(
    run(`visibleActorAssets().some(a=>a.name===${JSON.stringify(name)})`),
    'battle return must load the registered Layanganak image',
  );
  assert.equal(
    run('images["img/followers/follower-atlas-17.webp"]'),
    undefined,
    'never request an invented atlas file',
  );
  assert.equal(run(`images[${JSON.stringify(name)}]`), run('followerSources.get(17).image'));

  // Finish the other scene assets, leaving only Layanganak to load and prepare.
  run(`for(const asset of visibleActorAssets()){
    Object.assign(images[asset.name],{complete:true,naturalWidth:512});
  }
  for(const p of visibleRegionIndices().flatMap(i=>regionPoints(i))){
    serviceCells.set(p.portrait,{});castCells.set(p.portrait,{});
  }
  Object.assign(followerSources.get(17).image,{complete:true,naturalWidth:0});
  paintedScene=sceneToken();refreshLoadingState()`);
  const overlay = game.nodes.get('sceneLoading');
  assert.equal(overlay.style.display, 'flex', 'a real follower download failure offers retry');
  const sourceImage = run('followerSources.get(17).image');
  const onload = sourceImage.onload;
  run('retryMap()');
  assert.equal(run('followerSources.get(17).image'), sourceImage, 'retry keeps sprite preparation');
  assert.equal(sourceImage.onload, onload);
  assert(sourceImage.src.startsWith(`${name}?retry=`), 'retry requests the actual source file');
  run('followerSources.get(17).image.naturalWidth=512;refreshLoadingState()');
  assert.equal(overlay.style.display, 'flex', 'download must wait for sprite preparation');
  run('followerCells.set("17:0:0",{canvas:{},rect:[0,0,1,1]});refreshLoadingState()');
  assert.equal(overlay.style.display, 'none', 'the prepared follower reveals the map after victory');

  const reloaded = setup(game.storage);
  assert.equal(reloaded.run('followingMon().id'), 26);
  assert.equal(reloaded.run('state.team[1].hp'), 0);
  assert.equal(reloaded.run('state.region'), 1);
  assert.equal(reloaded.run('state.wins'), wins + 1, 'victory progress survives reload');

  // Every directional follower must use its registered asset, including custom names.
  for (let id = 0; id < 70; id++) {
    run(`state.team=[makeMon(${id})]`);
    const frame = run(`followerFrameFor(${id})`);
    const source = run(`followerSources.get(${frame.sheet})`);
    assert(source, `registered follower source for species ${id}`);
    assert(
      fs.existsSync(path.join(__dirname, '../web', source.name)),
      `follower image exists for species ${id}: ${source.name}`,
    );
    assert(
      run('visibleActorAssets()').some(a => a.name === source.name),
      `loading uses the registered source for species ${id}`,
    );
  }
  for (let id = 70; id < 80; id++) {
    run(`state.team=[makeMon(${id})]`);
    assert(
      run('visibleActorAssets()').some(a => a.name === run(`creaturePortraitPath(${id})`)),
      `portrait fallback uses the same species ${id}`,
    );
  }
  console.log(
    'PASS Tempurayap victory with Layanganak, loading/retry/preparation, saved progress and all 80 follower sources',
  );
}
main().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

