/* Shared Node VM harness. Every test runs the shipped page: all scripts from
   web/index.html, in its order. */
const fs = require('fs'),
  vm = require('vm'),
  path = require('path');
const DIST = path.join(__dirname, '../web');
const SCRIPT_ORDER = [
  ...fs.readFileSync(path.join(DIST, 'index.html'), 'utf8').matchAll(/<script src="([^"]+)"/g),
].map(m => m[1]);

function element() {
  return {
    innerHTML: '',
    textContent: '',
    className: '',
    disabled: false,
    hidden: false,
    dataset: {},
    classList: {
      add() {},
      remove() {},
      toggle() {},
      contains() {
        return false;
      },
    },
    style: {},
    querySelector() {
      return null;
    },
    querySelectorAll() {
      return [];
    },
    addEventListener() {},
    setAttribute() {},
    removeAttribute() {},
    append() {},
    appendChild() {},
    insertBefore() {},
    remove() {},
    focus() {},
    getContext() {
      return {
        fillRect() {},
        arc() {},
        rect() {},
        clip() {},
        measureText: t => ({ width: t.length * 7 }),
      };
    },
    getBoundingClientRect() {
      return { left: 0, top: 0, width: 960, height: 640 };
    },
  };
}

// afterScript(file, sandbox) runs after each script, for tests that watch the page being assembled.
function setup(storage = {}, { afterScript } = {}) {
  const nodes = new Map(),
    listeners = {},
    frames = [];
  const math = Object.create(Math);
  math.random = () => 0.5;
  const sandbox = {
    console,
    Math: math,
    setTimeout: f => {
      queueMicrotask(f);
      return 1;
    },
    clearTimeout() {},
    setInterval() {},
    requestAnimationFrame(cb) {
      frames.push(cb);
      return frames.length;
    },
    cancelAnimationFrame() {},
    Image: class {},
    localStorage: {
      getItem: k => storage[k],
      setItem: (k, v) => (storage[k] = v),
      removeItem: k => delete storage[k],
    },
    document: {
      body: { classList: { toggle() {} } },
      querySelector: () => ({ ...element(), requestFullscreen: async () => {} }),
      hidden: false,
      getElementById: id => {
        if (!nodes.has(id)) nodes.set(id, element());
        return nodes.get(id);
      },
      querySelectorAll: () => [],
      createElement: () => ({ ...element(), querySelector: () => element() }),
      addEventListener: (event, cb) => (listeners[event] ??= []).push(cb),
      activeElement: null,
    },
    window: { addEventListener() {} },
  };
  vm.createContext(sandbox);
  const load = file =>
    vm.runInContext(fs.readFileSync(path.join(DIST, file), 'utf8'), sandbox, { filename: file });
  for (const file of SCRIPT_ORDER) {
    load(file);
    afterScript?.(file, sandbox);
  }
  return {
    frames,
    listeners,
    sandbox,
    storage,
    nodes,
    load,
    boot() {
      for (const cb of listeners.DOMContentLoaded || []) cb();
    },
    run: s => vm.runInContext(s, sandbox),
    // A click reaches only the delegated handler whose data attribute is present.
    async click(dataset) {
      const closest = selector => {
        if (selector === 'button:not(:disabled)') return null;
        for (const [, attr, , value] of selector.matchAll(/data-([a-z-]+)(=["']?([^"'\]]*)["']?)?/g)) {
          const key = attr.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
          if (!dataset[key] || (value !== undefined && dataset[key] !== value)) return null;
        }
        return { dataset, disabled: false };
      };
      for (const cb of listeners.click || []) await cb({ target: { closest } });
    },
    key(key) {
      for (const cb of listeners.keydown || []) cb({ key, preventDefault() {} });
    },
  };
}

// The stylesheet in one canonical spelling (no whitespace, double quotes, no trailing
// semicolons), so assertions do not depend on how it is formatted.
const compactCSS = () =>
  fs
    .readFileSync(path.join(DIST, 'css/style.css'), 'utf8')
    .replace(/\s+/g, '')
    .replace(/'/g, '"')
    .replace(/;}/g, '}');
module.exports = { setup, SCRIPT_ORDER, compactCSS };

