/* English is found by looking up the Indonesian text a screen renders. If that
   text is edited in the code but not in i18n/id.json, the English silently
   disappears. This test makes that loud: every catalog entry must either be
   used by key or still occur in the source.

   tests/i18n-unverified.json lists entries that cannot be checked this way
   (text assembled from several pieces at run time, or left over from removed
   screens). A key may leave that list, never join it. */
const assert = require('node:assert/strict');
const fs = require('node:fs'),
  path = require('node:path');
const dist = path.join(__dirname, '../web');
const catalog = JSON.parse(fs.readFileSync(path.join(dist, 'i18n/id.json'), 'utf8'));
const sources = fs
  .readdirSync(dist, { recursive: true })
  .filter(name => /\.(js|html)$/.test(name) && !/(^|[\\/])(service-worker|messages)\.js$/.test(name))
  .map(name => fs.readFileSync(path.join(dist, name), 'utf8'))
  .join('\n');
// Keys built at run time: 'saveTransfer.' + key, `news.${key}.headline`, trainerText('region.' ...
const prefixes = new Set(
  [...sources.matchAll(/['"`]([A-Za-z][\w]*(?:\.[\w]+)*\.)(?:['"`]\s*\+|\$\{)/g)].map(match => match[1]),
);
const spellings = text => [
  text,
  text.replace(/'/g, "\\'"),
  text.replace(/"/g, '\\"'),
  text.replace(/&/g, '&amp;'),
];
// The lookup ignores case, so the comparison does too.
const folded = sources.toLowerCase();
const inSource = text => spellings(text.toLowerCase()).some(spelling => folded.includes(spelling));
const unverified = [];
for (const [key, text] of Object.entries(catalog)) {
  if (sources.includes(`'${key}'`) || sources.includes(`"${key}"`) || sources.includes('`' + key + '`'))
    continue;
  if ([...prefixes].some(prefix => key.startsWith(prefix))) continue;
  const parts = text.split(/\{\w+\}/).filter(part => part.trim().length >= 4);
  if (parts.length ? parts.every(inSource) : inSource(text)) continue;
  unverified.push(key);
}
const baselinePath = path.join(__dirname, 'i18n-unverified.json');
if (process.argv.includes('--write'))
  fs.writeFileSync(baselinePath, JSON.stringify(unverified, null, 1) + '\n');
const baseline = new Set(JSON.parse(fs.readFileSync(baselinePath, 'utf8')));
const drifted = unverified.filter(key => !baseline.has(key));
assert.deepEqual(
  drifted.map(key => `${key}: ${catalog[key].slice(0, 70)}`),
  [],
  'Indonesian text changed in the code without updating web/i18n/id.json and en.json',
);
const resolved = [...baseline].filter(key => !unverified.includes(key));
assert.deepEqual(resolved, [], 'these keys can now be verified; remove them from tests/i18n-unverified.json');
console.log(
  `PASS ${Object.keys(catalog).length - unverified.length} of ${Object.keys(catalog).length} catalog entries match the source; ${unverified.length} listed as unverifiable`,
);

