const assert = require('node:assert/strict');
const fs = require('node:fs');
const sharp = require('sharp');
const { setup } = require('./harness.cjs');
const { crossing, unlock } = require('./helpers/maps.cjs');

(async () => {
  const g = setup(),
    r = g.run;
  unlock(r);
  const chapters = [
    {
      index: 2,
      source: 'art/source/world-three.png',
      ids: [8, 10, 6, 11],
      originals: ['station', 'bengkel', 'pesisir-suaka', 'waduk'],
    },
    {
      index: 3,
      source: 'art/source/world-four.png',
      ids: [12, 14, 7, 13],
      originals: ['kaldera', 'league', 'puncak-sinyal', 'observatory'],
    },
  ];
  for (const { index, source, ids, originals } of chapters) {
    assert(r(`WORLD_CHAPTERS[${index}].seamless`), 'neighboring artwork is visible before crossing');
    assert.deepEqual(Array.from(r(`WORLD_CHAPTERS[${index}].tiles.flat()`)), ids);
    for (const [tile, id] of ids.entries()) {
      const image = r(`PLACES[${id}].image`);
      // The quartet source was later repainted map by map at full resolution; each
      // painting is its own native 3:2 scene, and the source sheet stays in the archive.
      assert(fs.existsSync(source), 'source sheet kept');
      const { width, height } = await sharp('web/' + image).metadata();
      assert(width >= 1536 && Math.abs(width / height - 1.5) < 0.01, `${image}: native 3:2 painting`);
      assert(
        fs.existsSync(
          `art/archive/world-${index === 2 ? 'three' : 'four'}-before-quartet/${originals[tile]}.webp`,
        ),
      );
      r(`state.region=${id};state.room=null;[state.x,state.y]=place().spawn;closeModal(true)`);
      assert(r('walkable(state.x,state.y)'), 'new spawn is on painted ground');
      for (const p of r('spots()')) {
        assert(r(`localTerrain(${id},${p.x},${p.y})`), `${id}: ${p.name} is on solid terrain`);
        assert(r(`routeTo(${p.x},${p.y})`), `${id}: ${p.name} is unreachable`);
      }
    }
  }
  // Every crossing inside chapters three and four.
  for (let n = 0; n < r('WORLD_LINKS.length'); n++)
    if (r(`chapterOf(WORLD_LINKS[${n}].from)`) >= 2) crossing(r, n, { offsets: [-5, 0, 5] });
  // Water, roofs and the crater stay solid in regular play; the debug toggle is separate.
  for (const [id, x, y] of [
    [6, 480, 350],
    [8, 760, 170],
    [10, 600, 240],
    [11, 650, 300],
    [12, 480, 100],
    // The observatory obelisk; the stairs in front of it lead to the lab door.
    [13, 550, 150],
    [14, 520, 150],
  ]) {
    assert(!r(`localTerrain(${id},${x},${y})`), `solid scenery ${id}/${x}/${y}`);
  }
  const saved = setup({
    'wargamon-v2': JSON.stringify({ ...r('state'), region: 6, room: null, x: 480, y: 350 }),
  });
  assert(saved.run('walkable(state.x,state.y)'), 'old saves on new water recover safely');
  console.log(
    'PASS eight native chapter paintings, continuous neighbors, every later-chapter border both ways, reachable activities, solid scenery, backups and save recovery',
  );
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

