/* HTTP crop/import/save flow runs in an isolated project. */
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const os = require('node:os');
const { spawn } = require('node:child_process');
const sharp = require('sharp');
(async () => {
  const root = path.resolve(__dirname, '..');
  const fixture = await fs.mkdtemp(path.join(os.tmpdir(), 'wargamon-art-http-'));
  let server;
  try {
    for (const name of [
      'scripts/map-art-editor.cjs',
      'scripts/build-offline-cache.py',
      'scripts/update-source-manifest.py',
      'README.md',
      'RELEASE.md',
      'package.json',
      'requirements-art.txt',
      'web/art-editor.html',
      'web/js/art-editor.js',
      'web/css/art-editor.css',
    ]) {
      const target = path.join(fixture, name);
      await fs.mkdir(path.dirname(target), { recursive: true });
      await fs.copyFile(path.join(root, name), target);
    }
    await fs.symlink(path.join(root, 'node_modules'), path.join(fixture, 'node_modules'), 'dir');
    await fs.mkdir(path.join(fixture, 'art'), { recursive: true });
    await fs.mkdir(path.join(fixture, 'web/img/maps/exterior'), { recursive: true });
    const original = await sharp({ create: { width: 256, height: 192, channels: 4, background: '#287d35' } })
      .webp({ lossless: true })
      .toBuffer();
    const image = 'img/maps/exterior/1-1.webp',
      imagePath = path.join(fixture, 'web', image);
    await fs.writeFile(imagePath, original);
    const floors = JSON.stringify({ maps: { 0: { image } } });
    await fs.writeFile(path.join(fixture, 'art/floors.json'), floors);
    await fs.writeFile(path.join(fixture, 'web/index.html'), '<title>fixture</title>');
    await fs.writeFile(path.join(fixture, 'web/service-worker.js'), 'original worker');
