/* Verify pixel guarantees and undo against disposable artwork, never the user's maps. */
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const sharp = require('sharp');
const editor = require('../scripts/map-art-editor.cjs');
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
(async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'wargamon-map-art-'));
  try {
    await fs.mkdir(path.join(root, 'art/source'), { recursive: true });
    await fs.mkdir(path.join(root, 'web/img/maps/exterior'), { recursive: true });
    const raw = Buffer.alloc(256 * 192 * 4);
    for (let y = 0; y < 192; y++)
      for (let x = 0; x < 256; x++) {
        const i = (y * 256 + x) * 4;
        raw[i] = x;
        raw[i + 1] = y;
        raw[i + 2] = (x * 7 + y * 3) % 256;
        raw[i + 3] = 255;
      }
    const original = await sharp(raw, { raw: { width: 256, height: 192, channels: 4 } })
      .png()
      .toBuffer();
    const mapName = 'web/img/maps/exterior/1-1.webp';
    await fs.writeFile(path.join(root, mapName), original);
    await fs.writeFile(path.join(root, 'web/img/maps/exterior/1-2.webp'), original);
    await fs.writeFile(
      path.join(root, 'art/floors.json'),
      JSON.stringify({
        maps: {
          0: { image: mapName.slice(4) },
          1: { image: 'img/maps/exterior/1-2.webp' },
          6: { image: 'img/maps/exterior/3-1.webp' },
        },
      }),
    );
    const base = {
      action: 'prepare',
      key: '0',
      revision: hash(original),
      rect: { x: 64, y: 60, width: 80, height: 64 },
      padding: 64,
      prompt: 'Replace one tree with a bench.',
    };
    await assert.rejects(
      editor.prepare(root, { ...base, rect: { ...base.rect, x: 0 } }),
      /locked map border/,
    );
    await assert.rejects(editor.prepare(root, { ...base, key: '../secret' }), /Unknown outdoor map/);
    await assert.rejects(editor.prepare(root, { ...base, revision: 'stale' }), /Map changed/);
    const record = await editor.prepare(root, base);
    assert.equal(
      hash(await fs.readFile(path.join(root, mapName))),
      hash(original),
      'preparation never edits map art',
    );
    const crop = await editor.pixels(
      await fs.readFile(path.join(root, '.map-art-edits', record.id, 'context.png')),
    );
    const changed = Buffer.from(crop.data);
    // A local object plus a global lighting drift, as in the failed ChatGPT
    // return. Edge matching must remove the drift without blurring details.
    for (let y = 0; y < crop.height; y++)
      for (let x = 0; x < crop.width; x++) {
        const i = (y * crop.width + x) * 4;
        changed[i] += 40;
        changed[i + 1] += 40;
        if (x >= 84 && x < 124 && y >= 74 && y < 108) {
          changed[i] = 240;
          changed[i + 1] = 100;
          changed[i + 2] = 80;
        }
      }
    const candidate = await sharp(changed, { raw: { width: crop.width, height: crop.height, channels: 4 } })
      .png()
      .toBuffer();
    const request = { id: record.id, image: candidate.toString('base64') };
    const wrong = await sharp(candidate).resize(128, 128).png().toBuffer();
    await assert.rejects(
      editor.preview(root, { ...request, image: wrong.toString('base64'), fit: true }),
      /different frame/,
    );
    const enlarged = await sharp(candidate)
      .resize(crop.width * 3, crop.height * 3)
      .png()
      .toBuffer();
    const scaled = await editor.preview(root, { ...request, image: enlarged.toString('base64') });
    assert(scaled.report.fitted, 'a larger crop with the same frame is reduced proportionally');
    assert.equal(scaled.report.outside, 0);
    const preview = await editor.preview(root, request);
    assert.equal(preview.report.outside, 0);
    assert(preview.report.inside > 0 && preview.report.inside <= (80 - 2) * (64 - 2));
    assert(preview.report.edgeMatched);
    assert(preview.report.warnings.length, 'redrawn surrounding context is explicitly flagged');
    const output = await fs.readFile(path.join(root, '.map-art-edits', record.id, 'result.webp'));
    const actual = await editor.pixels(output);
    assert.equal(editor.verify(await editor.pixels(original), actual, record.rect).outside, 0);
    // The tint is eliminated at the patch edges and the candidate's native
    // texture elsewhere is retained, rather than feathering back the old object.
    for (const [x, y] of [
      [64, 60],
      [65, 61],
      [70, 80],
      [100, 60],
    ])
      assert.deepEqual(
        actual.data.subarray((y * 256 + x) * 4, (y * 256 + x) * 4 + 4),
        raw.subarray((y * 256 + x) * 4, (y * 256 + x) * 4 + 4),
      );
    assert.equal(
      actual.data[(90 * 256 + 100) * 4],
      200,
      'replacement detail is retained after lighting correction',
    );
    await assert.rejects(
      editor.save(root, { id: record.id, candidate: preview.candidate }, false),
      /Check the close-up/,
    );
    assert.equal(
      hash(await fs.readFile(path.join(root, mapName))),
      hash(original),
      'preview never edits map art',
    );
    await assert.rejects(editor.save(root, { id: record.id, candidate: 'wrong' }, false), /Preview/);
    const saved = await editor.save(
      root,
      { id: record.id, candidate: preview.candidate, reviewed: true },
      false,
    );
    assert.equal(hash(await fs.readFile(path.join(root, mapName))), saved.saved.image);
    assert.equal(
      hash(await fs.readFile(path.join(root, 'web/img/maps/exterior/1-2.webp'))),
      hash(original),
      'neighbor bytes are untouched',
    );
    await fs.writeFile(path.join(root, mapName), candidate);
    await assert.rejects(editor.undo(root, { id: record.id }, false), /Map changed/);
    await fs.writeFile(path.join(root, mapName), output);
    await editor.undo(root, { id: record.id }, false);
    assert.equal(
      hash(await fs.readFile(path.join(root, mapName))),
      hash(original),
      'undo restores exact original bytes',
    );
    const stale = await editor.prepare(root, base);
    const stalePreview = await editor.preview(root, { ...request, id: stale.id });
    await fs.writeFile(path.join(root, mapName), output);
    await assert.rejects(
      editor.save(root, { id: stale.id, candidate: stalePreview.candidate, reviewed: true }, false),
      /stale edit/,
    );
    await fs.writeFile(path.join(root, mapName), original);
    const oldJob = path.join(root, '.map-art-edits', record.id, 'edit.json');
    const oldRecord = JSON.parse(await fs.readFile(oldJob));
    delete oldRecord.report.edgeMatched;
    await fs.writeFile(oldJob, JSON.stringify(oldRecord));
    await assert.rejects(
      editor.save(root, { id: record.id, candidate: preview.candidate, reviewed: true }, false),
      /old hard-paste/,
    );
    // Native chapter quadrant updates must preserve all other source pixels as well.
    const master = await sharp({ create: { width: 512, height: 384, channels: 4, background: '#38702b' } })
      .composite([{ input: original, left: 0, top: 192 }])
      .png()
      .toBuffer();
    await fs.writeFile(path.join(root, 'art/source/world-three.png'), master);
    await fs.writeFile(path.join(root, 'web/img/maps/exterior/3-1.webp'), original);
    const atlas = await editor.prepare(root, { ...base, key: '6' });
    assert(atlas.master, 'matching source quadrant is tracked');
    const atlasPreview = await editor.preview(root, { ...request, id: atlas.id });
    await editor.save(root, { id: atlas.id, candidate: atlasPreview.candidate, reviewed: true }, false);
    const masterAfter = await fs.readFile(path.join(root, 'art/source/world-three.png'));
    assert.equal(
      editor.verify(await editor.pixels(master), await editor.pixels(masterAfter), {
        left: 64,
        top: 252,
        width: 80,
        height: 64,
      }).outside,
      0,
    );
    await editor.undo(root, { id: atlas.id }, false);
    assert.equal(hash(await fs.readFile(path.join(root, 'art/source/world-three.png'))), hash(master));
    // A build failure cannot leave a partially saved map.
    const failure = await editor.prepare(root, base);
    const failurePreview = await editor.preview(root, { ...request, id: failure.id });
    await assert.rejects(
      editor.save(root, { id: failure.id, candidate: failurePreview.candidate, reviewed: true }),
      /Build failed/,
    );
    assert.equal(
      hash(await fs.readFile(path.join(root, mapName))),
      hash(original),
      'failed build restores image',
    );
    console.log(
      'PASS map artwork edge lighting match, retained texture, review required, crop context, locked borders, decoded outside pixels, native dimensions, neighbor protection, source quadrant, stale edits, undo and failed-save rollback',
    );
  } finally {
    await fs.rm(root, { recursive: true, force: true });
  }
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

/* Verify exported raster detail and browser backing pixels without changing world scale. */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const sharp = require('sharp');
const { setup } = require('./harness.cjs');
const { onePainting, unlock } = require('./helpers/maps.cjs');
(async () => {
  const g = setup(),
    r = g.run;
  const maps = r('PLACES.map(p => ({ image:p.image, tile:p.tile }))');
  const records = JSON.parse(fs.readFileSync('art/independent-map-generation.json')).records;
  assert.equal(records.length, maps.length);
  assert.equal(new Set(maps.map(p => p.image)).size, maps.length);
  const current = JSON.parse(fs.readFileSync('art/independent-map-generation.json')).chapterWorlds;
  assert.equal(current.crops.length, 8);
  assert.equal(current.independentChapterTwo.length, 4);
  for (const [i, p] of maps.entries()) {
    const image = await sharp('web/' + p.image).metadata();
    const crop = current.crops.find(c => c.id === i);
    // Chapters three and four began as crops of one sheet and were later repainted
    // map by map at full size; the fourth chapter's paintings are 1020px tall.
    assert.equal(image.width, i === 0 ? 1535 : 1536, `${p.image}: native supplied width`);
    assert.equal(
      image.height,
      /exterior\/4-/.test(p.image) ? 1020 : 1024,
      `${p.image}: native supplied height`,
    );
    if (crop) {
      assert.equal(crop.image, p.image);
      assert.equal(crop.resized, false);
      assert.equal(crop.lossless, true);
    }
    assert.equal(p.tile, -1, `${p.image}: complete image rather than sheet crop`);
    assert.equal(records[i].image, p.image);
    assert.equal(records[i].export.resized, false);
    assert.equal(records[i].export.cropped, false);
    onePainting(r, i);
  }
  unlock(r);
  r('state.region=7');
  assert(
    r('worldRoute(globalPoint(7,{x:480,y:585}),globalPoint(7,{x:340,y:365}))'),
    'mountain terrace has a usable painted approach',
  );
  // The open meadow north of the road and the dirt road itself; south of it are bushes.
  for (const [x, y] of [
    [405, 330],
    [405, 500],
    [565, 500],
    [180, 500],
  ])
    assert(r(`localTerrain(1,${x},${y})`), 'meadow and road are walkable');
  const world = g.nodes.get('world');
  const camera = r('[camera.width,camera.height]');
  for (const [width, height, ratio] of [
    [900, 600, 1],
    [1440, 960, 2],
  ]) {
    world.getBoundingClientRect = () => ({ width, height });
    g.sandbox.devicePixelRatio = ratio;
    r('resizeWorldCanvas()');
    assert.equal(world.width, width * ratio);
    assert.equal(world.height, height * ratio);
    assert.deepEqual(r('[camera.width,camera.height]'), camera, 'display density must not change game zoom');
  }
  console.log(
    'PASS independent chapter-two images, eight repainted later-chapter maps, complete-image rendering and normal/Retina backing pixels at unchanged camera zoom',
  );
})().catch(e => {
  console.error(e);
  process.exitCode = 1;
});

