/* A new art-cache version must fetch current images, while retaining offline fallback. */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const source = fs.readFileSync(path.join(__dirname, '../web/service-worker.js'), 'utf8');
const base = 'http://localhost:8000/';
const calls = [],
  writes = [],
  additions = [];
let cached,
  offline = false;
const cache = {
  match: async () => cached?.clone(),
  put: async (key, response) => writes.push([key, await response.text()]),
  add: async request => additions.push(request),
};
class LocalRequest extends Request {
  constructor(input, options) {
    super(typeof input === 'string' ? new URL(input, base) : input, options);
  }
}
const context = vm.createContext({
  URL,
  Request: LocalRequest,
  console,
  setTimeout,
  clearTimeout,
  AbortController,
  self: { navigator: {}, location: { origin: 'http://localhost:8000' }, addEventListener() {} },
  caches: { open: async () => cache },
  fetch: async (request, options) => {
    calls.push([request.url, options]);
    if (offline) throw Error('offline');
    return new Response('new map');
  },
});
vm.runInContext(source, context);
(async () => {
  const plain = new LocalRequest('img/maps/exterior/1-1.webp');
  assert.equal(await (await context.artResponse(plain)).text(), 'new map');
  assert.equal(calls[0][1].cache, 'no-cache', 'new version revalidates the HTTP image');
  assert.equal(writes[0][0], plain.url);

  cached = new Response('cached map');
  assert.equal(await (await context.artResponse(plain)).text(), 'cached map');
  assert.equal(calls.length, 1, 'current game cache stays cache-first');

  const retry = new LocalRequest('img/maps/exterior/1-1.webp?retry=1');
  assert.equal(await (await context.artResponse(retry)).text(), 'new map');
  assert.equal(calls[1][1].cache, 'no-cache');
  assert.equal(writes[1][0], plain.url, 'retry never creates a duplicate cache key');
  offline = true;
  assert.equal(await (await context.artResponse(retry)).text(), 'cached map');

  cached = undefined;
  await context.warmArt();
  assert(additions.length > 100);
  assert(
    additions.every(request => request.cache === 'reload'),
    'precache also bypasses old HTTP art',
  );
  console.log('PASS new artwork revalidates HTTP images, caches stable keys and preserves offline fallback');
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

