/* Run every suite and report all failures; one broken suite must not hide the next. */
const { spawnSync } = require('node:child_process'),
  fs = require('node:fs'),
  path = require('node:path');
const SUPPORT = new Set(['harness.cjs', 'run-all.cjs']);
const suites = fs
  .readdirSync(__dirname)
  .filter(name => name.endsWith('.cjs') && !SUPPORT.has(name))
  .sort();
const failed = [];
for (const name of suites) {
  const result = spawnSync(process.execPath, [path.join(__dirname, name)], {
    cwd: path.join(__dirname, '..'),
    encoding: 'utf8',
  });
  const output = (result.stdout + result.stderr).trim();
  // A suite that exits cleanly without reporting PASS did not reach its last assertion.
  if (result.status === 0 && /^PASS /m.test(output)) {
    console.log(output);
    continue;
  }
  failed.push(name);
  console.log(
    `FAIL ${name}${result.status === 0 ? ' (exited without a PASS line)' : ''}\n${output
      .split('\n')
      .map(line => '  ' + line)
      .join('\n')}`,
  );
}
console.log(`\n${suites.length - failed.length}/${suites.length} suites passed`);
if (failed.length) {
  console.log('Failed: ' + failed.join(', '));
  process.exitCode = 1;
}

