/* Every function has one definition. A later script must never replace an
   earlier function: the page is a set of modules, not a stack of patches. */
const assert = require('node:assert/strict');
const fs = require('node:fs'),
  path = require('node:path');
const { setup, SCRIPT_ORDER } = require('./harness.cjs');
const seen = new Map(),
  replaced = [];
setup(
  {},
  {
    afterScript(file, sandbox) {
      for (const [name, value] of Object.entries(sandbox)) {
        if (typeof value !== 'function') continue;
        const first = seen.get(name);
        if (!first) seen.set(name, { value, file });
        else if (first.value !== value) {
          replaced.push(`${name}: ${first.file} -> ${file}`);
          seen.set(name, { value, file });
        }
      }
    },
  },
);
assert.deepEqual(replaced, [], 'functions redefined by a later script');
// The same rule in the source: no "const before=name; name=function" wrappers.
const dist = path.join(__dirname, '../web');
for (const file of SCRIPT_ORDER) {
  if (file.startsWith('i18n/messages')) continue;
  const source = fs.readFileSync(path.join(dist, file), 'utf8');
  const wrapper = source.match(
    /(?:^|[;\n])\s*(?:const|let)\s+\w+\s*=\s*(\w+)\s*;\s*\1\s*=\s*(?:async\s+)?(?:function\b|\()/,
  );
  assert(!wrapper, `${file} wraps ${wrapper?.[1]} instead of editing its one definition`);
}
assert(seen.size > 300, 'the page defines its functions as globals');
console.log(`PASS ${seen.size} functions across ${SCRIPT_ORDER.length} scripts, each defined once`);

