(async () => {
  const sample = [
    { path: 'wargamon/README.md', data: 'Wargamon' },
    { path: 'wargamon/web/index.html', data: '<!doctype html>' },
  ];
  const zip = new Uint8Array(await makeSourceZip(sample).arrayBuffer());
  const view = new DataView(zip.buffer),
    decoder = new TextDecoder();
  let cursor = 0;
  for (const file of sample) {
    assert.equal(view.getUint32(cursor, true), 0x04034b50);
    const size = view.getUint32(cursor + 18, true),
      nameLength = view.getUint16(cursor + 26, true);
    assert.equal(decoder.decode(zip.slice(cursor + 30, cursor + 30 + nameLength)), file.path);
    assert.equal(
      decoder.decode(zip.slice(cursor + 30 + nameLength, cursor + 30 + nameLength + size)),
