      assert.equal(run('battle'), null);
      assert.equal(run('locked'), false);
      assert.equal(run('modalKind'), 'defeat');
      assert(run('state.team.every(m=>m.hp===0)'));
      assert.match(game.nodes.get('modal').innerHTML, /HP semua Wargamonmu tetap 0/);
      const defeated = snapshot(run);
      assert.equal(defeated.money, 25000, 'no rescue fee');
