      assert.equal(defeated.room, room);
      assert.deepEqual([defeated.x, defeated.y], Array.from(run('place().spawn')), 'no teleport');
      assert.deepEqual(defeated.returnPosition, { region: 3, x: 420, y: 520 });
      assert.deepEqual(
        defeated.team.map(m => m.id),
        [0, 1],
        'keep the owned team',
      );
      assert.equal(defeated.team[0].fullness, 20, "keep the last turn's hunger, without rescue food");
      assert(run('hasCondition(state.team[0],"poison")'), 'no automatic cleansing');
      assert.equal(defeated.storage.length, 1);
      assert.equal(defeated.storage[0].hp, defeated.storage[0].max);
      assert.equal(defeated.balls, 8);
      assert.equal(defeated.potions, 5);
      assert.equal(defeated.revive, 2);
      assert.equal(run('trackFollower()'), null);
      assert.equal(run('followingMon()'), null);
      run('drawFollower(null,0);updateWildLocator()');
      assert(run('locator.hidden'));
      assert(game.nodes.get('wildBtn').disabled);
      assert.match(game.nodes.get('hint').textContent, /Berjalan sendiri/);
      const required = run('visibleActorAssets().map(a=>a.name)');
