      const offset = run('[[10,0],[-10,0],[0,10],[0,-10]].find(([dx,dy])=>walkable(state.x+dx,state.y+dy))');
      assert(offset, 'floor has a walking neighbor');
      run(`movement(${offset[0]},${offset[1]})`);
      assert.deepEqual(
