  assert(w('state.team.every(m=>m.hp===m.max)'), 'only the chosen rest service restores HP');
  assert.equal(w('state.money'), 25000, 'rest stops are free, and a defeat charges no fee');
  assert.deepEqual([w('state.x'), w('state.y')], atRest);
  assert(w('hasCondition(state.team[0],"poison")'), 'rest still preserves conditions');
  assert(w('trackFollower()'), 'a recovered teammate follows again');

  const charms = setup(),
    c = charms.run;
  unlock(c);
  c('state.team=[makeMon(0),makeMon(1)];startBattle(null,[[5,5]]);state.team[0].hp=0');
  assert.equal(await c('partyFaint()'), false);
  assert.equal(c('state.team[0].id'), 1, 'healthy reserve still switches in');
  c(
    'endBattle();state.team=[makeMon(0),makeMon(1)];state.team[0].heldItem="rescue";startBattle(null,[[5,5]]);state.team[0].hp=0',
  );
  assert.equal(await c('partyFaint()'), false);
  assert.equal(
    c('state.team[0].hp'),
