  assert.equal(c('state.team[0].hp'), c('Math.ceil(state.team[0].max*.25)'), 'charm saves the last teammate');
  assert.equal(c('state.team[0].rescueUsed'), true);
  c('state.team[0].hp=0');
  assert.equal(await c('partyFaint()'), true, 'a used charm does not act twice');
  assert(c('state.team.every(m=>m.hp===0)'));
  c('closeModal();medicineMenu("revive");state.revive=1');
  await charms.click({ over: 'medicine', key: 'revive', id: '1' });
  assert.equal(c('followingMon().id'), 1, 'manual recovery of a reserve picks a conscious follower');
  assert.equal(c('state.team[0].hp'), 0);

  const league = setup(),
