  assert.equal(l('leagueState().active'), false);
  assert.equal(l('leagueState().stage'), 0);
  assert.equal(l('state.region'), 14);
  assert.equal(l('state.room'), 'leaguearena');
  assert.deepEqual([l('state.x'), l('state.y')], position);
  assert.equal(l('state.team[0].hp'), 0);
  assert.equal(l('state.money'), 25000);

  console.log(
    'PASS full defeat keeps 0 HP, location, money and collection; solo walking, manual recovery, reload, encounter guards, partial fainting, charms and League defeat',
  );
}
