"""Validate and bundle catalogs. Translators edit JSON, never combat rules."""
import json
import re
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[1] / 'web' / 'i18n'
metadata = json.loads((root / 'locales.json').read_text())
catalogs = {code: json.loads((root / f'{code}.json').read_text()) for code in metadata}
source = catalogs['id']
for code, catalog in catalogs.items():
    if set(source) != set(catalog):
        raise SystemExit(f'{code}: locale keys do not match Indonesian')
    for key, text in catalog.items():
        if not isinstance(text, str) or not text:
            raise SystemExit(f'{code}: missing message {key}')
        placeholders = lambda value: set(re.findall(r'\{(\w+)\}', value))
        if placeholders(source[key]) != placeholders(text):
            raise SystemExit(f'{code}: placeholder mismatch in {key}')

content = (
    'globalThis.WARGAMON_LOCALES=' + json.dumps(metadata, ensure_ascii=False) + ';\n' +
    'globalThis.WARGAMON_MESSAGES=' + json.dumps(catalogs, ensure_ascii=False) + ';\n')
# --check fails when messages.js no longer matches the JSON catalogs.
if '--check' in sys.argv:
    if (root / 'messages.js').read_text() != content:
        raise SystemExit('web/i18n/messages.js is out of date. Run python3 scripts/build-i18n.py')
    print(f'Locale bundle is current: {len(source)} message keys in {len(catalogs)} languages')
else:
    (root / 'messages.js').write_text(content)
    print(f'Locale catalogs: {len(source)} matched message keys in {len(catalogs)} languages')

"""Build the offline service worker from the shipped files.

The shell (page, scripts, styles) installs atomically and is served network
first, so a deploy is never pinned behind an old cache. Runtime art is served
cache first and fetched in the background once the first map is on screen.
Editable inputs in web/source-art/ are not runtime art and are never cached.

Run with --check to fail when web/service-worker.js is out of date.
"""
from pathlib import Path
import hashlib
import json
import re
import sys

root = Path(__file__).resolve().parents[1] / 'web'
target = root / 'service-worker.js'
html = (root / 'index.html').read_text()
shell = sorted(set(['./', 'index.html'] + re.findall(r'<script src="([^"]+)"', html) + re.findall(r'<link rel="stylesheet" href="([^"]+)"', html)))
art = sorted(p.relative_to(root).as_posix() for p in root.rglob('*')
             if p.suffix.lower() in ('.webp', '.png', '.jpg', '.jpeg') and 'source-art' not in p.relative_to(root).parts)
missing = [name for name in shell if name != './' and not (root / name).is_file()]
if missing:
    raise SystemExit(f'Missing offline assets: {missing}')


def version(names):
    digest = hashlib.sha256()
    for name in names:
        digest.update(name.encode())
        if name != './':
            digest.update((root / name).read_bytes())
    return digest.hexdigest()[:12]


source = '''/* Generated by scripts/build-offline-cache.py. Do not edit. */
const SHELL_CACHE = 'wargamon-shell-%(shell_version)s';
const ART_CACHE = 'wargamon-art-%(art_version)s-http2';
const SHELL = %(shell)s;
const ART = %(art)s;
const ART_FILE = /\\.(?:webp|png|jpe?g)$/i;
const SHELL_TIMEOUT = 4000;

// A shell that did not download completely must not replace a working one.
self.addEventListener('install', event => {
 event.waitUntil((async () => {
  const cache = await caches.open(SHELL_CACHE);
  await cache.addAll(SHELL.map(name => new Request(name, {cache: 'reload'})));
  await self.skipWaiting();
 })());
});
self.addEventListener('activate', event => {
 event.waitUntil((async () => {
  const keep = new Set([SHELL_CACHE, ART_CACHE]);
  await Promise.all((await caches.keys()).filter(key => key.startsWith('wargamon-') && !keep.has(key)).map(key => caches.delete(key)));
  await self.clients.claim();
 })());
});

// The page asks for offline art after its first map is painted. Art the
// player has already seen is in the cache; this fills in the rest.
async function warmArt() {
 if(self.navigator.connection?.saveData) return;
 const cache = await caches.open(ART_CACHE);
 let next = 0;
 await Promise.all(Array.from({length: 3}, async () => {
  while(next < ART.length) {
   const name = ART[next++];
   if(await cache.match(name)) continue;
   try { await cache.add(new Request(name, {cache: 'reload'})); }
   catch(error) { console.warn('Offline art unavailable:', name, error); }
  }
 }));
}
self.addEventListener('message', event => {
 if(event.data === 'warm-art') event.waitUntil(warmArt());
});

// Retry requests add ?retry=<time>. They must reach the network, and the
// result is stored under the plain file name so retries never pile up.
async function artResponse(request) {
 const cache = await caches.open(ART_CACHE);
 const url = new URL(request.url);
 const key = url.origin + url.pathname;
 if(!url.search) {
  const hit = await cache.match(key);
  if(hit) return hit;
 }
 try {
  // A new game-art cache must not inherit stale artwork from the browser's HTTP cache.
  const response = await fetch(request, {cache: 'no-cache'});
  if(response.ok) cache.put(key, response.clone()).catch(() => {});
  return response;
 } catch(error) {
  const hit = await cache.match(key);
  if(hit) return hit;
  throw error;
 }
}
async function shellResponse(request) {
 const cache = await caches.open(SHELL_CACHE);
 const cached = await cache.match(request) || (request.mode === 'navigate' ? await cache.match('./') || await cache.match('index.html') : undefined);
 const controller = new AbortController();
 // Only a request with an offline copy may give up on a slow network.
 const timer = cached ? setTimeout(() => controller.abort(), SHELL_TIMEOUT) : 0;
 try {
  // Revalidate with the server: the browser's own HTTP cache must not answer with an old script.
  const response = await fetch(request, {signal: controller.signal, cache: 'no-cache'});
  if(response.ok) cache.put(request, response.clone()).catch(() => {});
  return response;
 } catch(error) {
  if(cached) return cached;
  throw error;
 } finally {
  clearTimeout(timer);
 }
}
self.addEventListener('fetch', event => {
 const url = new URL(event.request.url);
 if(event.request.method !== 'GET' || url.origin !== self.location.origin || url.pathname.startsWith('/__editor/')) return;
 event.respondWith(ART_FILE.test(url.pathname) ? artResponse(event.request) : shellResponse(event.request));
});
''' % {
    'shell_version': version(shell),
    'art_version': version(art),
    'shell': json.dumps(shell, ensure_ascii=False),
    'art': json.dumps(art, ensure_ascii=False),
}

size = sum((root / name).stat().st_size for name in art) / 1e6
if '--check' in sys.argv:
    if not target.is_file() or target.read_text() != source:
        raise SystemExit('web/service-worker.js is out of date. Run python3 scripts/build-offline-cache.py')
    print(f'Offline cache is current: {len(shell)} shell files, {len(art)} art files ({size:.1f} MB)')
else:
    target.write_text(source)
    print(f'Offline cache: {len(shell)} shell files, {len(art)} art files ({size:.1f} MB)')

"""Serve the game locally, with permanent walking-area saves from the debug editor."""
import argparse
import hashlib
import json
import secrets
import shutil
import subprocess
import sys
import threading
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlsplit

PROJECT = Path(__file__).resolve().parents[1]
ENDPOINT = '/__editor/floors'
MAX_BODY = 200_000
ART_ENDPOINT = '/__editor/art'


def art_action(server, data):
    result = subprocess.run(
        [server.node, str(server.project / 'scripts/map-art-editor.cjs'), str(server.project)],
        input=json.dumps(data), text=True, capture_output=True, timeout=60,
    )
    try:
        response = json.loads(result.stdout)
    except ValueError as error:
        raise RuntimeError('Map image editor is unavailable') from error
    if not response.get('ok'):
        raise ValueError(response.get('error', 'Image edit failed'))
    return response['result']


def atomic_write(path, data):
    temporary = path.with_name(path.name + '.editor-tmp')
    try:
        temporary.write_bytes(data)
        temporary.replace(path)
    finally:
        temporary.unlink(missing_ok=True)


def revision(project):
    digest = hashlib.sha256()
    for name in ['art/floors.json', 'web/js/data/floors.js']:
        digest.update((project / name).read_bytes())
    return digest.hexdigest()


def save_floors(project, data, node):
    if not isinstance(data, dict) or data.get('version') != 1:
        raise ValueError('Invalid floor archive')
    maps = data.get('maps')
    if not isinstance(maps, dict) or not maps or len(maps) > 64:
        raise ValueError('Invalid maps')
    config = json.loads((project / 'art/floors.json').read_text())
    for key, value in maps.items():
        scene = config['maps'].get(key)
        if not scene or not isinstance(value, dict):
            raise ValueError('Unknown map or interior')
        rows = value.get('rows')
        if value.get('image') != scene.get('image') or not isinstance(rows, list) or len(rows) != 65:
            raise ValueError('Map does not match the project')
        if any(not isinstance(row, str) or len(row) != 97 or set(row) - {'#', '.'} for row in rows):
            raise ValueError('Invalid walking-area grid')
        scene['rows'] = rows
    # Keep source and generated files together, including on a failed build.
    names = ['art/floors.json', 'web/js/data/floors.js', 'web/service-worker.js', 'web/source-manifest.json']
    backups = {name: (project / name).read_bytes() for name in names}
    try:
        atomic_write(project / names[0], (json.dumps(config, ensure_ascii=False, indent=2) + '\n').encode())
        commands = [
            [node, 'scripts/build-floors.cjs', '--only', ','.join(maps)],
            [sys.executable, 'scripts/build-offline-cache.py'],
            [sys.executable, 'scripts/update-source-manifest.py'],
        ]
        for command in commands:
            subprocess.run(command, cwd=project, check=True, capture_output=True, timeout=60)
    except Exception:
        for name, content in backups.items():
            atomic_write(project / name, content)
        raise
    return {'saved': list(maps), 'revision': revision(project)}


class EditorHandler(SimpleHTTPRequestHandler):
    def __init__(self, request, client_address, server):
        super().__init__(request, client_address, server, directory=str(server.project / 'web'))

    def respond(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def local_request(self):
        host = self.headers.get('Host', '')
        origin = self.headers.get('Origin')
        try:
            parsed = urlsplit('http://' + host)
            return (parsed.hostname in {'localhost', '127.0.0.1'}
                    and parsed.port == self.server.server_port
                    and (origin is None or origin == 'http://' + host)
                    and self.client_address[0] == '127.0.0.1')
        except ValueError:
            return False

    def do_GET(self):
        parsed = urlsplit(self.path)
        if parsed.path == ART_ENDPOINT or parsed.path == ART_ENDPOINT + '/file':
            if not self.local_request():
                return self.respond(403, {'error': 'Local editor only'})
            try:
                if parsed.path == ART_ENDPOINT:
                    with self.server.edit_lock:
                        result = art_action(self.server, {'action': 'info'})
                    return self.respond(200, {**result, 'token': self.server.edit_token})
                query = parse_qs(parsed.query)
                edit = query.get('edit', [''])[0]
                name = query.get('name', [''])[0]
                if len(edit) != 32 or any(c not in '0123456789abcdef' for c in edit) or name not in {'context.png', 'selection.png', 'preview.png', 'before.png', 'prompt.txt'}:
                    return self.respond(400, {'error': 'Invalid editor file'})
                content = (self.server.project / '.map-art-edits' / edit / name).read_bytes()
                self.send_response(200)
                self.send_header('Content-Type', 'text/plain; charset=utf-8' if name.endswith('.txt') else 'image/png')
                self.send_header('Content-Length', str(len(content)))
                self.send_header('Cache-Control', 'no-store')
                self.end_headers()
                self.wfile.write(content)
                return
            except ValueError as error:
                return self.respond(400, {'error': str(error)})
            except FileNotFoundError:
                return self.respond(404, {'error': 'Editor file unavailable'})
            except Exception as error:
                print('Image editor failed:', error, file=sys.stderr, flush=True)
                return self.respond(500, {'error': 'Image editor unavailable'})
        if parsed.path != ENDPOINT:
            return super().do_GET()
        if not self.local_request():
            return self.respond(403, {'error': 'Local editor only'})
        with self.server.edit_lock:
            self.respond(200, {'token': self.server.edit_token, 'revision': revision(self.server.project)})

    def do_POST(self):
        endpoint = urlsplit(self.path).path
        if endpoint not in {ENDPOINT, ART_ENDPOINT}:
            return self.respond(404, {'error': 'Unknown endpoint'})
        if not self.local_request() or self.headers.get('X-Wargamon-Editor') != self.server.edit_token:
            return self.respond(403, {'error': 'Local editor only'})
        if self.headers.get_content_type() != 'application/json':
            return self.respond(415, {'error': 'Expected an editor save'})
        try:
            size = int(self.headers.get('Content-Length', '0'))
            if size <= 0 or size > (34_000_000 if endpoint == ART_ENDPOINT else MAX_BODY):
                return self.respond(413, {'error': 'Invalid request size'})
            data = json.loads(self.rfile.read(size))
            with self.server.edit_lock:
                if endpoint == ART_ENDPOINT:
                    if not isinstance(data, dict):
                        return self.respond(400, {'error': 'Invalid image edit'})
                    return self.respond(200, art_action(self.server, data))
                if not isinstance(data, dict) or data.get('revision') != revision(self.server.project):
                    return self.respond(409, {'error': 'Project changed; reload before saving'})
                result = save_floors(self.server.project, data, self.server.node)
            self.respond(200, result)
        except (ValueError, TypeError) as error:
            self.respond(400, {'error': str(error) if endpoint == ART_ENDPOINT else 'Invalid map edits; nothing was changed'})
        except Exception as error:
            print('Editor save failed:', error, file=sys.stderr, flush=True)
            self.respond(500, {'error': 'Build failed; project files were restored'})

    def end_headers(self):
        # Local edits and scripts should be visible immediately on refresh.
        if urlsplit(self.path).path != ENDPOINT:
            self.send_header('Cache-Control', 'no-cache')
        super().end_headers()


def make_server(project=PROJECT, port=8000, node=None):
    server = ThreadingHTTPServer(('127.0.0.1', port), EditorHandler)
    server.project = Path(project)
    server.node = node or shutil.which('node')
    if not server.node:
        server.server_close()
        raise RuntimeError('Node.js is required for permanent editor saves')
    server.edit_token = secrets.token_urlsafe(32)
    server.edit_lock = threading.Lock()
    return server


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--port', type=int, default=8000)
    args = parser.parse_args()
    with make_server(port=args.port) as server:
        print(f'Wargamon: http://localhost:{server.server_port}/?debug (permanent map saving enabled)', flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass

/* Build walkable floors from the map paintings (configuration in art/floors.json).

   Most scenes are traced by hand over the painting (`trace: true`): a cell of the 10px
   movement grid is floor when it lies inside one of the `floor` shapes or within
   `reach` of one of the `lanes` lines, and not inside a `solid` shape (furniture,
   stalls, buses, lamp posts). With `foliage: share`, cells whose painting is mostly leaf
   green (trees, hedges, planters) are solid too, except on `lawns`. `open` shapes are
   floor whatever lies under them (stairs, a gap between planters).

   The older colour-learned scenes use a cell when it lies inside one of the map's
   `open` polygons, or when
     - most ground around it has one of the map's ground colours: a named `ground`
       type, or close to the colour of one of the `samples` (pixels known to be floor),
     - it lies within `reach` of one of the traced `corridors` lines, or inside one of
       the `areas` polygons, when the map has them,
     - it is not inside a `blocked` polygon, and
     - it connects to one of the `seeds`.
   `bridges` force short gaps closed where shadow or a lamp post hides the ground.

   node scripts/build-floors.cjs                      writes web/js/data/floors.js
   node scripts/build-floors.cjs --only 0,1,2,gang      rebuilds these floors, retaining the others
