  if (poly.e) return ((x - poly.e[0]) / poly.e[2]) ** 2 + ((y - poly.e[1]) / poly.e[3]) ** 2 <= 1;
  if (typeof poly[0] === 'number') return x >= poly[0] && x <= poly[2] && y >= poly[1] && y <= poly[3];
  let hit = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i],
      [xj, yj] = poly[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) hit = !hit;
