function foliageCells(data, config) {
  const leaf = new Uint8Array(W * H);
  for (let i = 0; i < W * H; i++) {
    const r = data[i * 3],
      g = data[i * 3 + 1],
      b = data[i * 3 + 2];
    leaf[i] = g > 45 && g > r + 10 && g >= b ? 1 : 0;
  }
  const out = new Uint8Array(COLS * ROWS);
  for (let row = 0; row < ROWS; row++)
    for (let col = 0; col < COLS; col++) {
      const cx = col * 10,
        cy = row * 10;
      if ((config.lawns || []).some(shape => inside(shape, cx, cy))) continue;
      let hits = 0,
        total = 0;
      for (let y = cy - 6; y <= cy + 6; y++)
        for (let x = cx - 6; x <= cx + 6; x++) {
          if (x < 0 || y < 0 || x >= W || y >= H) continue;
          total++;
          hits += leaf[y * W + x];
