// floor only where at least `share` of the painting around it is that ground.
function groundCells(data, config) {
  const tests = config.ground.map(name => GROUND[name]);
  const out = new Uint8Array(COLS * ROWS);
  for (let row = 0; row < ROWS; row++)
    for (let col = 0; col < COLS; col++) {
      let hits = 0,
        total = 0;
      for (let y = row * 10 - 6; y <= row * 10 + 6; y++)
        for (let x = col * 10 - 6; x <= col * 10 + 6; x++) {
          if (x < 0 || y < 0 || x >= W || y >= H) continue;
          const i = (y * W + x) * 3,
            r = data[i],
            g = data[i + 1],
            b = data[i + 2];
          total++;
          if (tests.some(t => t(r, g, b, (r + g + b) / 3, Math.max(r, g, b) - Math.min(r, g, b)))) hits++;
