    for (let col = 0; col < COLS; col++) {
      const x = col * 10,
        y = row * 10;
      const floor =
        (config.floor || []).some(shape => inside(shape, x, y)) ||
        (near(config.lanes || [], x, y) && (!ground || ground[row * COLS + col]));
      const open = (config.open || []).some(shape => inside(shape, x, y));
      const obstacle = (config.solid || []).some(shape => inside(shape, x, y)),
