  if (config.rows) {
    if (
      !Array.isArray(config.rows) ||
      config.rows.length !== ROWS ||
      config.rows.some(row => typeof row !== 'string' || row.length !== COLS || !/^[#.]+$/.test(row))
    )
      throw new Error('Invalid saved floor grid: ' + config.image);
