  }
  if (config.walkEverywhere) return { rows: Array(ROWS).fill('#'.repeat(COLS)), art, cells: COLS * ROWS };
  if (config.trace)
    return {
      rows: traced(
        config,
        config.foliage ? foliageCells(data, config) : null,
        config.ground ? groundCells(data, config) : null,
