  // Props on the ground (planters, barrels, bikes) are a minority and drop out.
  if (config.learn) {
    const bin = (r, g, b) => ((r >> 4) << 8) | ((g >> 4) << 4) | (b >> 4);
    const counts = new Map();
    let total = 0;
    for (let y = 0; y < H; y += 2)
