  const rows = [];
  for (let row = 0; row < ROWS; row++) {
    let line = '';
    for (let col = 0; col < COLS; col++) line += floor[row * COLS + col] ? '#' : '.';
    rows.push(line);
  }
  return { rows, art, cells: queue.length };
