(async () => {
  const preview = process.argv.indexOf('--preview');
  const onlyArg = process.argv.indexOf('--only'),
    only = onlyArg < 0 ? null : new Set((process.argv[onlyArg + 1] || '').split(',')),
    output = path.join(root, 'web/js/data/floors.js');
  if (only && [...only].some(key => !maps[key])) throw new Error('Unknown floor in --only');
  // Targeted art replacements must not require rebuilding unrelated old sheets.
  const previous = only
      ? require('node:vm').runInNewContext(fs.readFileSync(output, 'utf8') + '; FLOORS')
      : {},
    built = Object.fromEntries(Object.entries(previous).map(([key, rows]) => [key, { rows }]));
  for (const [key, config] of Object.entries(maps)) {
    if (only && !only.has(key)) continue;
    // Shared rooms start from the same floor, but an authored grid belongs only
    // to the selected room and must survive targeted and complete rebuilds.
    built[key] = config.same && !config.rows ? built[config.same] : await build(config);
    built[key].cells = built[key].rows.join('').split('#').length - 1;
  }
  for (const value of Object.values(built)) value.cells = value.rows.join('').split('#').length - 1;
  const body = Object.entries(built)
    .map(
      ([key, { rows }]) =>
        `  ${/^\w+$/.test(key) ? key : `'${key}'`}: [\n${rows.map(r => `    '${r}',`).join('\n')}\n  ],`,
    )
    .join('\n');
  fs.writeFileSync(
    output,
    `/* Generated by scripts/build-floors.cjs from the map paintings and art/floors.json. Do not edit.
   One character per 10px cell, in image coordinates: # is floor. Keys are region numbers
   or room keys. */
const FREE_WALK_MAPS = new Set([${Object.entries(maps)
      .filter(([, config]) => config.walkEverywhere)
      .map(([key]) => (/^\d+$/.test(key) ? key : `'${key}'`))
      .join(', ')}]);
const FLOORS = {
${body}
};
`,
  );
  console.log(
    'Floors:',
    Object.entries(built)
      .map(([key, b]) => `${key} ${b.cells} cells`)
      .join(', '),
  );
  if (preview > 0) {
    const { rows, art } = built[process.argv[preview + 1]];
    const over = Buffer.alloc(W * H * 4);
    rows.forEach((line, row) => {
      for (let col = 0; col < COLS; col++) {
        if (line[col] !== '#') continue;
        for (let y = row * 10 - 3; y <= row * 10 + 3; y++)
          for (let x = col * 10 - 3; x <= col * 10 + 3; x++)
            if (x >= 0 && y >= 0 && x < W && y < H) over.set([0, 255, 80, 190], (y * W + x) * 4);
      }
    });
    await sharp(art)
      .composite([{ input: over, raw: { width: W, height: H, channels: 4 } }])
      .png()
      .toFile(process.argv[preview + 2]);
  }
})();

/* Local crop/import editor. The generator never owns the final map canvas. */
const fs = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');
const { spawnSync } = require('node:child_process');
const sharp = require('sharp');
const EDGE = 32;
const NAMES = [
  'Sukamaju',
  'Padang Ojek',
  'Hutan Pinggir Kota',
  'Terminal Rame',
  'Kota Beton',
  'Festival Arus',
  'Pesisir Suaka',
  'Puncak Sinyal',
  'Stasiun Sela',
  'Pasar Malam',
  'Kampung Bengkel',
  'Taman Waduk',
  'Jalur Kaldera',
  'Observatorium Sunyi',
  'Liga Nusantara',
];
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const store = root => path.join(root, '.map-art-edits');
async function json(file) {
  return JSON.parse(await fs.readFile(file, 'utf8'));
}
async function writeJSON(file, data) {
  await fs.writeFile(file, JSON.stringify(data, null, 2));
}
async function pixels(bytes) {
  const { data, info } = await sharp(bytes, { limitInputPixels: 24_000_000 })
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  if (info.channels !== 4) throw new Error('Unsupported image channels');
  return { data, width: info.width, height: info.height };
}
async function source(root, key) {
  const config = await json(path.join(root, 'art/floors.json'));
  const image = config.maps[key]?.image;
  if (!/^(?:\d+|gang)$/.test(String(key)) || !/^img\/maps\/exterior\/[1-4]-[1-4]\.webp$/.test(image || ''))
    throw new Error('Unknown outdoor map');
  const file = path.join(root, 'web', image);
  const bytes = await fs.readFile(file);
  const metadata = await sharp(bytes).metadata();
  if (metadata.depth !== 'uchar' || metadata.pages > 1)
    throw new Error('Only still, 8-bit map images are supported');
  return {
    key,
    image,
    file,
    bytes,
    revision: hash(bytes),
    width: metadata.width,
    height: metadata.height,
    name: key === 'gang' ? 'Gang Senggol' : NAMES[Number(key)],
  };
}
function jobPath(root, id) {
  if (!/^[a-f0-9]{32}$/.test(id || '')) throw new Error('Invalid edit session');
  return path.join(store(root), id);
}
async function job(root, id) {
  const dir = jobPath(root, id);
