}
function rectangle(value, width, height) {
  if (!value || !['x', 'y', 'width', 'height'].every(k => Number.isInteger(value[k])))
    throw new Error('Invalid selection');
  const { x, y, width: w, height: h } = value;
  if (w < 32 || h < 32 || x < EDGE || y < EDGE || x + w > width - EDGE || y + h > height - EDGE)
    throw new Error('Select at least 32 × 32 pixels inside the locked map border');
