/* Convert legacy PNG inputs to lossless WebP without changing alpha or dimensions. */
const fs = require('node:fs'),
  path = require('node:path'),
  sharp = require('sharp');
const root = path.resolve(__dirname, '../web');
(async () => {
  for (const name of fs.readdirSync(root).filter(n => n.endsWith('.png'))) {
    const source = path.join(root, name),
      target = path.join(root, name.replace(/\.png$/, '.webp'));
    if (fs.existsSync(target)) throw Error('Target already exists: ' + target);
    const before = await sharp(source).metadata();
    await sharp(source).webp({ lossless: true, effort: 4 }).toFile(target);
