  let svg = `<svg width="${w * sc}" height="${h * sc}" xmlns="http://www.w3.org/2000/svg">`;
  for (let x = Math.ceil(x0 / 25) * 25; x <= x0 + w; x += 25)
    svg += `<line x1="${sx(x)}" y1="0" x2="${sx(x)}" y2="${h * sc}" stroke="#fff" stroke-opacity="${x % 100 ? 0.15 : 0.45}"/>${x % 50 ? '' : `<text x="${sx(x) + 2}" y="12" fill="#ff0" font-size="12">${x}</text>`}`;
  for (let y = Math.ceil(y0 / 25) * 25; y <= y0 + h; y += 25)
    svg += `<line x1="0" y1="${sy(y)}" x2="${w * sc}" y2="${sy(y)}" stroke="#fff" stroke-opacity="${y % 100 ? 0.15 : 0.45}"/>${y % 50 ? '' : `<text x="2" y="${sy(y) + 12}" fill="#ff0" font-size="12">${y}</text>`}`;
  for (const [x, y] of floor)
    if (x >= x0 && y >= y0 && x <= x0 + w && y <= y0 + h)
      svg += `<rect x="${sx(x - 5)}" y="${sy(y - 5)}" width="${10 * sc}" height="${10 * sc}" fill="#39ff6a" fill-opacity="0.38"/>`;
  for (const q of p.points) {
    if (q.person)
      svg += `<rect x="${sx(q.x - 15)}" y="${sy(q.y - (isRoom ? 48 : 38))}" width="${30 * sc}" height="${(isRoom ? 56 : 46) * sc}" fill="none" stroke="#f33" stroke-width="2"/>`;
    svg += `<circle cx="${sx(q.x)}" cy="${sy(q.y)}" r="6" fill="#ff4d6d" stroke="#000"/><text x="${sx(q.x) + 10}" y="${sy(q.y) + 4}" fill="#fff" font-size="12" stroke="#000" stroke-width="0.4">${q.name.replace(/[&<>]/g, '')}</text>`;
  }
  svg += '</svg>';
  const out = `map-preview-${key}.png`;
  await sharp(crop)
    .composite([{ input: Buffer.from(svg) }])
    .png()
    .toFile(out);
  console.log(out);
})();

/* Repaint the League arena from its source hall (web/source-art/leaguearena-hall.webp):
   the badminton court, net, umpire chairs and shuttlecock signs become a battle floor
   with four Elite stations and the Champion's dais, and the banners name the League.

   node scripts/repaint-league-arena.cjs   writes web/img/maps/interior/leaguearena.webp

   The art is 768 x 512; game coordinates are 960 x 640, so every game position is
   multiplied by 0.8. The Elite stations match ROOMS.leaguearena in js/data/places.js. */
const sharp = require('sharp');
const path = require('node:path');
const root = path.join(__dirname, '..');
const k = 0.8;
const g = n => Math.round(n * k);
// Game positions of the Elite stations and the Champion's dais.
const STATIONS = [
  { x: 270, y: 250, color: '#3fa7e0', glow: '#9bd8f7' }, // Arus
  { x: 690, y: 250, color: '#9b6be0', glow: '#cdb5f5' }, // Tempo
  { x: 270, y: 395, color: '#e0583f', glow: '#f5ae9f' }, // Bara
  { x: 690, y: 395, color: '#5bbf5b', glow: '#ade3a8' }, // Tenaga
];
const CHAMPION = { x: 480, y: 215 };
const floor = { left: g(155), top: g(185), right: g(855), bottom: g(432) };
const cx = g(480),
  cy = g(318);
const star = (x, y, r, fill) => {
  const pts = [];
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5,
      d = i % 2 ? r * 0.45 : r;
    pts.push(`${(x + d * Math.cos(a)).toFixed(1)},${(y + d * Math.sin(a)).toFixed(1)}`);
  }
  return `<polygon points="${pts.join(' ')}" fill="${fill}"/>`;
};
const text = (x, y, size, words) =>
  `<text x="${x}" y="${y}" font-family="Arial Black, Impact, sans-serif" font-size="${size}" fill="#f4f1e6" text-anchor="middle" letter-spacing="0.5">${words}</text>`;
let svg = `<svg width="768" height="512" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges">`;
// The battle floor: a stone platform with a raised rim and a tiled surface.
const w = floor.right - floor.left,
  h = floor.bottom - floor.top;
svg += `<rect x="${floor.left - 3}" y="${floor.top - 3}" width="${w + 6}" height="${h + 8}" fill="#1a2233"/>`;
svg += `<rect x="${floor.left}" y="${floor.top}" width="${w}" height="${h}" fill="#3b4f73"/>`;
svg += `<rect x="${floor.left + 6}" y="${floor.top + 6}" width="${w - 12}" height="${h - 12}" fill="#33466a"/>`;
for (let x = floor.left + 6 + 24; x < floor.right - 6; x += 24)
  svg += `<rect x="${x}" y="${floor.top + 6}" width="1" height="${h - 12}" fill="#2a3a59"/>`;
for (let y = floor.top + 6 + 24; y < floor.bottom - 6; y += 24)
  svg += `<rect x="${floor.left + 6}" y="${y}" width="${w - 12}" height="1" fill="#2a3a59"/>`;
// Light from the hall's ceiling lamps along the front edge.
svg += `<rect x="${floor.left}" y="${floor.bottom - 2}" width="${w}" height="4" fill="#0e1420"/>`;
// The League ring in the middle.
svg += `<g shape-rendering="geometricPrecision">`;
svg += `<circle cx="${cx}" cy="${cy}" r="62" fill="#2c3d5e" stroke="#d9b45a" stroke-width="4"/>`;
svg += `<circle cx="${cx}" cy="${cy}" r="48" fill="none" stroke="#b08a3a" stroke-width="2"/>`;
svg += star(cx, cy, 30, '#d9b45a');
svg += star(cx, cy, 15, '#f3dc9a');
// Elite stations: a coloured pad with a light rim.
for (const s of STATIONS) {
  svg += `<ellipse cx="${g(s.x)}" cy="${g(s.y) - 2}" rx="27" ry="13" fill="${s.color}" stroke="${s.glow}" stroke-width="2"/>`;
  svg += `<ellipse cx="${g(s.x)}" cy="${g(s.y) - 2}" rx="17" ry="7" fill="none" stroke="#1a2233" stroke-opacity="0.35" stroke-width="2"/>`;
}
svg += `</g>`;
// The Champion's dais: two gold steps under the far stands.
svg += `<rect x="${g(CHAMPION.x) - 46}" y="${g(CHAMPION.y) - 26}" width="92" height="30" fill="#8d6a2b"/>`;
svg += `<rect x="${g(CHAMPION.x) - 40}" y="${g(CHAMPION.y) - 22}" width="80" height="22" fill="#d9b45a"/>`;
svg += `<rect x="${g(CHAMPION.x) - 40}" y="${g(CHAMPION.y) - 22}" width="80" height="3" fill="#f3dc9a"/>`;
svg += `<rect x="${g(CHAMPION.x) - 46}" y="${g(CHAMPION.y) + 4}" width="92" height="3" fill="#5c431a"/>`;
// Banners: the League's name instead of the badminton federation's.
const banner = (x, y, bw, bh) =>
  `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" fill="#1d2b62"/><rect x="${x + 2}" y="${y + 2}" width="${bw - 4}" height="${bh - 4}" fill="none" stroke="#c9b06a" stroke-width="1"/>`;
svg += banner(g(383), g(22), g(584) - g(383), g(86) - g(22));
svg += `<g shape-rendering="geometricPrecision">`;
svg += text(g(480), g(48), 17, 'LIGA') + text(g(480), g(76), 17, 'NUSANTARA');
svg += star(g(408), g(52), 11, '#d9b45a') + star(g(552), g(52), 11, '#d9b45a');
svg += `</g>`;
svg += banner(g(116), g(114), g(215) - g(116), g(181) - g(114));
svg += `<g shape-rendering="geometricPrecision">`;
svg +=
  text(g(165), g(137), 10, 'RAIH MIMPI') +
  text(g(165), g(155), 10, 'BERSAMA') +
  text(g(165), g(173), 10, 'TIMMU');
svg += `</g>`;
svg += banner(g(866), g(266), g(925) - g(866), g(422) - g(266));
svg += `<g shape-rendering="geometricPrecision">`;
svg += star(g(895), g(292), 13, '#d9b45a');
svg += text(g(895), g(332), 11, 'SATU') + text(g(895), g(354), 11, 'TIM') + text(g(895), g(376), 11, 'SATU');
svg += text(g(895), g(398), 10, 'TEKAD');
svg += `</g></svg>`;
(async () => {
  await sharp(path.join(root, 'web/source-art/leaguearena-hall.webp'))
    .composite([{ input: Buffer.from(svg) }])
    .webp({ quality: 90 })
    .toFile(path.join(root, 'web/img/maps/interior/leaguearena.webp'));
  console.log('web/img/maps/interior/leaguearena.webp');
})();
